ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'research'))
from smishguard.bantaytext_workflow import experiment_matrix


def build():
    source=(ROOT/'research/smishguard/bantaytext_workflow.py').read_text(encoding='utf-8')
